import{_ as i,o as t,c as a,O as o}from"./chunks/framework.dbd1b522.js";const s="/imgs/leds/SpwYUgw.jpeg",n="/imgs/leds/ZsTnjem.jpeg",r="/imgs/leds/f0onbjb.jpeg",l="/imgs/leds/pM31O08.jpeg",d="/imgs/leds/LaJmm4Z.jpeg",h="/imgs/leds/UkLVPci.jpeg",g="/imgs/leds/a1j6zHi.jpeg",p="/imgs/leds/UTtd5bG.jpeg",c="/imgs/leds/DNpVzY3.jpeg",m="/imgs/leds/4VWqUiZ.jpeg",u="/imgs/leds/zdj9WUu.png",b="/imgs/leds/Bi6Og87.jpeg",w="/imgs/leds/dCNMQaZ.jpeg",y="/imgs/leds/vuhsckU.jpeg",f="/imgs/leds/s1eqJiE.jpeg",E="/imgs/leds/l57tEmr.jpg",z=JSON.parse('{"title":"Assembling V4 LED Kits","description":"How to assemble V4, V4 mini and V4E IR LED boards, wire them up and check polarity before mounting them in your headset.","frontmatter":{"title":"Assembling V4 LED Kits","description":"How to assemble V4, V4 mini and V4E IR LED boards, wire them up and check polarity before mounting them in your headset."},"headers":[],"relativePath":"how_to_build/led_v4_setup.md","filePath":"how_to_build/led_v4_setup.md","lastUpdated":1792278920000}'),L={name:"how_to_build/led_v4_setup.md"};function _(k,e,D,V,q,v){return t(),a("div",null,[...e[0]||(e[0]=[o('<p>Pardon the mess this page is WIP; more docs for other configurations and assembly are in the works.</p><h1 id="how-to-assemble-v4-led-kits" tabindex="-1">How to assemble V4 LED kits <a class="header-anchor" href="#how-to-assemble-v4-led-kits" aria-label="Permalink to &quot;How to assemble V4 LED kits&quot;">​</a></h1><h2 id="v4-mini" tabindex="-1">V4 mini <a class="header-anchor" href="#v4-mini" aria-label="Permalink to &quot;V4 mini&quot;">​</a></h2><h3 id="getting-to-know-your-hardware" tabindex="-1">Getting to know your hardware <a class="header-anchor" href="#getting-to-know-your-hardware" aria-label="Permalink to &quot;Getting to know your hardware&quot;">​</a></h3><p>There are 3 main components of an IR LED kit; the mainboard, LEDs and wires.</p><h3 id="mainboard" tabindex="-1">Mainboard <a class="header-anchor" href="#mainboard" aria-label="Permalink to &quot;Mainboard&quot;">​</a></h3><p>Below is the V4 mini mainboard with major features labeled. <img src="'+s+'" alt="V4 mini mainboard with the main features labelled" loading="lazy" decoding="async"><img src="'+n+'" alt="Reverse side of the V4 mini mainboard" loading="lazy" decoding="async"></p><h3 id="leds" tabindex="-1">LEDs <a class="header-anchor" href="#leds" aria-label="Permalink to &quot;LEDs&quot;">​</a></h3><p>There are 2 different types of LED boards. The one you should have more of are the &quot;N&quot; LEDs. N stands for Normal, these make up 3 of the LEDs per eye. <img src="'+r+'" alt="V4 N (normal) IR LED board, LED side" loading="lazy" decoding="async"><img src="'+l+'" alt="V4 N (normal) IR LED board, connector side" loading="lazy" decoding="async"></p><p>The second type is the &quot;E&quot; LEDs. E stands for End as these are put at the end of the LED strand.</p><p><img src="'+d+'" alt="V4 E (end) IR LED board, LED side" loading="lazy" decoding="async"><img src="'+h+'" alt="V4 E (end) IR LED board, connector side" loading="lazy" decoding="async"></p><p>In future orders the &quot;E&quot; LEDs will be purple for easier distinction. <img src="'+g+'" alt="Purple V4 E (end) LED board used on future orders" loading="lazy" decoding="async"></p><h3 id="wires" tabindex="-1">Wires <a class="header-anchor" href="#wires" aria-label="Permalink to &quot;Wires&quot;">​</a></h3><p>The included wires are a bit special, they have 3 pins on the connectors but only 2 wires are attached. <img src="'+p+'" alt="Three-pin LED cable with only two wires attached" loading="lazy" decoding="async"></p><p>This distinction is crucial in assembling a kit as the wires need to go in a specific orientation outlined in the assembly picture which shows the pins without wires as dashes - - -.</p><h3 id="wiring-up-v4-mini" tabindex="-1">Wiring up V4 mini <a class="header-anchor" href="#wiring-up-v4-mini" aria-label="Permalink to &quot;Wiring up V4 mini&quot;">​</a></h3><p>Start by plugging in the long wires to the main board like shown.</p><p><img src="'+c+'" alt="Long LED wires plugged into the V4 mini mainboard" loading="lazy" decoding="async"><img src="'+m+'" alt="LED wire connectors seated in the V4 mini mainboard" loading="lazy" decoding="async"></p><p>Then connect the wires to LEDs in the sequence:</p><p><code>Mainboard -&gt; N LED -&gt; N LED -&gt; N LED -&gt; E LED</code></p><p>You need to <strong>pay very close attention</strong> to the <strong>orientation</strong> of the wires so that the missing wire is facing the correct way. The following image shows a kit fully assembled:</p><p><img src="'+u+'" alt="Fully assembled V4 mini kit with mainboard and both LED strands" loading="lazy" decoding="async"></p><p>Here is an example of the right eye&#39;s LED strand.</p><p><img src="'+b+'" alt="Right eye V4 mini LED strand connected to the mainboard" loading="lazy" decoding="async"></p><h2 id="v4-lite" tabindex="-1">V4 Lite <a class="header-anchor" href="#v4-lite" aria-label="Permalink to &quot;V4 Lite&quot;">​</a></h2><h3 id="getting-to-know-v4-lite" tabindex="-1">Getting to know V4 Lite <a class="header-anchor" href="#getting-to-know-v4-lite" aria-label="Permalink to &quot;Getting to know V4 Lite&quot;">​</a></h3><p>V4 Lite is a soldering-required approach to LEDs. There are a few specific caveats to know before assembling and using this hardware.</p><ol><li><p>The board must be supplied with 5V.</p><ul><li>Other voltages may result in darker/non-functioning LEDs.</li></ul></li><li><p>You must change resistors if you change from a single or dual eye setup to the other.</p><ul><li>Not doing so will result in too dim of LEDs or extremely bright LEDs. Ensure you are always using the correct one for your application.</li></ul></li><li><p>Shorts on the main board can result in damaged hardware, dangerously bright LEDs, or nonfunctioning hardware.</p><ul><li>Please ensure there are no shorts (even very small stray solder strands) between any pins or solder joints on the main board or LEDs.</li></ul></li></ol><h3 id="wiring-up-v4-lite" tabindex="-1">Wiring up V4 Lite <a class="header-anchor" href="#wiring-up-v4-lite" aria-label="Permalink to &quot;Wiring up V4 Lite&quot;">​</a></h3><p>First, decide if you want dual eye or single eye operation and pick the appropriate resistor.</p><p><strong><strong>Single Eye:</strong></strong> Use the 130ohm resistor marked with Black, Black, and Gold middle rings:</p><p><img src="'+w+'" alt="130 ohm resistor for single eye V4 Lite operation" loading="lazy" decoding="async"></p><p><strong><strong>Dual Eye:</strong></strong> Use the 65ohm resistor marked with Yellow, White and Gold middle rings:</p><p><img src="'+y+'" alt="65 ohm resistor for dual eye V4 Lite operation" loading="lazy" decoding="async"></p><p>Now, solder the resistor on the board (any orientation), and then the black 3 pin voltage regulator (orientation matters, solder on the side with the white outline and have it fit in the outline&#39;s shape).</p><p><img src="'+f+'" alt="V4 Lite mainboard with resistor and voltage regulator soldered in" loading="lazy" decoding="async"></p><p>Now, wire up the LEDs like shown.</p><p><img src="'+E+'" alt="V4 Lite kit fully wired and assembled" loading="lazy" decoding="async"></p>',38)])])}const P=i(L,[["render",_]]);export{z as __pageData,P as default};
